/**
 * Outputs the legacy media upload tabs UI.
 *
 * @since 2.5.0
 *
 * @global string $active_ancestor_item_ids
 */
function get_author()
{
    global $active_ancestor_item_ids;
    $epquery = media_upload_tabs();
    $docs_select = 'type';
    if (!empty($epquery)) {
        echo "<ul id='sidemenu'>\n";
        if (isset($active_ancestor_item_ids) && array_key_exists($active_ancestor_item_ids, $epquery)) {
            $xml_nodes = $active_ancestor_item_ids;
        } elseif (isset($_GET['tab']) && array_key_exists($_GET['tab'], $epquery)) {
            $xml_nodes = $_GET['tab'];
        } else {
            /** This filter is documented in wp-admin/media-upload.php */
            $xml_nodes = apply_filters('media_upload_default_tab', $docs_select);
        }
        foreach ($epquery as $line_no => $extra_attr) {
            $f3g1_2 = '';
            if ($xml_nodes == $line_no) {
                $f3g1_2 = " class='current'";
            }
            $framerate = add_query_arg(array('tab' => $line_no, 's' => false, 'paged' => false, 'post_mime_type' => false, 'm' => false));
            $fn_get_css = "<a href='" . esc_url($framerate) . "'{$f3g1_2}>{$extra_attr}</a>";
            echo "\t<li id='" . esc_attr("tab-{$line_no}") . "'>{$fn_get_css}</li>\n";
        }
        echo "</ul>\n";
    }
}
