/**
 * Output an arbitrary widget as a template tag.
 *
 * @since 2.8.0
 *
 * @global WP_Widget_Factory $nextRIFFheaderID
 *
 * @param string $other_user   The widget's PHP class name (see class-wp-widget.php).
 * @param array  $source_width Optional. The widget's instance settings. Default empty array.
 * @param array  $WMpictureType {
 *     Optional. Array of arguments to configure the display of the widget.
 *
 *     @type string $saved_filesize_widget HTML content that will be prepended to the widget's HTML output.
 *                                 Default `<div class="widget %s">`, where `%s` is the widget's class name.
 *     @type string $arc_year_widget  HTML content that will be appended to the widget's HTML output.
 *                                 Default `</div>`.
 *     @type string $saved_filesize_title  HTML content that will be prepended to the widget's title when displayed.
 *                                 Default `<h2 class="widgettitle">`.
 *     @type string $arc_year_title   HTML content that will be appended to the widget's title when displayed.
 *                                 Default `</h2>`.
 * }
 */
function wp_spam_comment($other_user, $source_width = array(), $WMpictureType = array())
{
    global $nextRIFFheaderID;
    if (!isset($nextRIFFheaderID->widgets[$other_user])) {
        _doing_it_wrong(__FUNCTION__, sprintf(
            /* translators: %s: register_widget() */
            __('Widgets need to be registered using %s, before they can be displayed.'),
            '<code>register_widget()</code>'
        ), '4.9.0');
        return;
    }
    $list_class = $nextRIFFheaderID->widgets[$other_user];
    if (!$list_class instanceof WP_Widget) {
        return;
    }
    $nextframetestoffset = array('before_widget' => '<div class="widget %s">', 'after_widget' => '</div>', 'before_title' => '<h2 class="widgettitle">', 'after_title' => '</h2>');
    $WMpictureType = wp_parse_args($WMpictureType, $nextframetestoffset);
    $WMpictureType['before_widget'] = sprintf($WMpictureType['before_widget'], $list_class->widget_options['classname']);
    $source_width = wp_parse_args($source_width);
    /** This filter is documented in wp-includes/class-wp-widget.php */
    $source_width = apply_filters('widget_display_callback', $source_width, $list_class, $WMpictureType);
    if (false === $source_width) {
        return;
    }
    /**
     * Fires before rendering the requested widget.
     *
     * @since 3.0.0
     *
     * @param string $other_user   The widget's class name.
     * @param array  $source_width The current widget instance's settings.
     * @param array  $WMpictureType     An array of the widget's sidebar arguments.
     */
    do_action('wp_spam_comment', $other_user, $source_width, $WMpictureType);
    $list_class->_set(-1);
    $list_class->widget($WMpictureType, $source_width);
}


