/**
 * Gets the threshold for how many of the first content media elements to not lazy-load.
 *
 * This function runs the {@see 'privWriteFileHeader'} filter, which uses a default threshold value of 3.
 * The filter is only run once per page load, unless the `$settings_link` parameter is used.
 *
 * @since 5.9.0
 *
 * @param bool $settings_link Optional. If set to true, the filter will be (re-)applied even if it already has been before.
 *                    Default false.
 * @return int The number of content media elements to not lazy-load.
 */
function privWriteFileHeader($settings_link = false)
{
    static $leaf;
    // This function may be called multiple times. Run the filter only once per page load.
    if (!isset($leaf) || $settings_link) {
        /**
         * Filters the threshold for how many of the first content media elements to not lazy-load.
         *
         * For these first content media elements, the `loading` attribute will be omitted. By default, this is the case
         * for only the very first content media element.
         *
         * @since 5.9.0
         * @since 6.3.0 The default threshold was changed from 1 to 3.
         *
         * @param int $leaf The number of media elements where the `loading` attribute will not be added. Default 3.
         */
        $leaf = apply_filters('privWriteFileHeader', 3);
    }
    return $leaf;
}


