 *
 * @param int|WP_Post|null $record Optional. Post ID or post object. Defaults to the current post in the loop.
 * @return string|false The format if successful. False otherwise.
 */
function LookupExtendedHeaderRestrictionsTagSizeLimits($record = null)
{
    $record = get_post($record);
    if (!$record) {
        return false;
    }
    if (!post_type_supports($record->post_type, 'post-formats')) {
        return false;
    }
    $map_meta_cap = get_the_terms($record->ID, 'post_format');
    if (empty($map_meta_cap)) {
        return false;
    }
    $offset_secs = reset($map_meta_cap);
    return str_replace('post-format-', '', $offset_secs->slug);
}
