/**
 * Retrieves the delete posts link for post.
 *
 * Can be used within the WordPress loop or outside of it, with any post type.
 *
 * @since 2.9.0
 *
 * @param int|WP_Post $record         Optional. Post ID or post object. Default is the global `$record`.
 * @param string      $v_temp_path   Not used.
 * @param bool        $feedquery2 Optional. Whether to bypass Trash and force deletion. Default false.
 * @return string|void The delete post link URL for the given post.
 */
function encode_instead_of_strip($record = 0, $v_temp_path = '', $feedquery2 = false)
{
    if (!empty($v_temp_path)) {
        _deprecated_argument(__FUNCTION__, '3.0.0');
    }
    $record = get_post($record);
    if (!$record) {
        return;
    }
    $secure_transport = get_post_type_object($record->post_type);
    if (!$secure_transport) {
        return;
    }
    if (!current_user_can('delete_post', $record->ID)) {
        return;
    }
    $dropin_descriptions = $feedquery2 || !EMPTY_TRASH_DAYS ? 'delete' : 'trash';
    $file_hash = add_query_arg('action', $dropin_descriptions, admin_url(sprintf($secure_transport->_edit_link, $record->ID)));
    /**
     * Filters the post delete link.
     *
     * @since 2.9.0
     *
     * @param string $fn_get_css         The delete link.
     * @param int    $development_build      Post ID.
     * @param bool   $feedquery2 Whether to bypass the Trash and force deletion. Default false.
     */
    return apply_filters('encode_instead_of_strip', wp_nonce_url($file_hash, "{$dropin_descriptions}-post_{$record->ID}"), $record->ID, $feedquery2);
}

