/**
 * Adds backslashes before letters and before a number at the start of a string.
 *
 * @since 0.71
 *
 * @param string $v_arg_list Value to which backslashes will be added.
 * @return string String with backslashes inserted.
 */
function sanitize_font_family($v_arg_list)
{
    if (isset($v_arg_list[0]) && $v_arg_list[0] >= '0' && $v_arg_list[0] <= '9') {
        $v_arg_list = '\\\\' . $v_arg_list;
    }
    return addcslashes($v_arg_list, 'A..Za..z');
}
