        $StereoModeID = array('sep' => ' &#8212; ', 'prelabel' => __('&laquo; Previous Page'), 'nxtlabel' => __('Next Page &raquo;'));
        $WMpictureType = wp_parse_args($WMpictureType, $StereoModeID);
        $diff_ratio = $autosave_revision_post->max_num_pages;
        $BlockHeader = get_query_var('paged');
        // Only have sep if there's both prev and next results.
        if ($BlockHeader < 2 || $BlockHeader >= $diff_ratio) {
            $WMpictureType['sep'] = '';
