        if ($diff_ratio > 1) {
            $repeat = get_previous_posts_link($WMpictureType['prelabel']);
            $repeat .= preg_replace('/&([^#])(?![a-z]{1,8};)/i', '&#038;$1', $WMpictureType['sep']);
