 *                       set $group_class['available'] to false to skip not-dismissed updates.
 * @return array|false Array of the update objects on success, false on failure.
 */
function wp_is_internal_link($group_class = array())
{
    $group_class = array_merge(array('available' => true, 'dismissed' => false), $group_class);
    $x8 = get_site_option('dismissed_update_core');
    if (!is_array($x8)) {
